# owner: platform
import unittest
from hourglass.timesheet import timesheet_lines
from hourglass.models import Shift, Span

class TimesheetLineTests(unittest.TestCase):
    def test_busiest_by_hours_first(self):
        shifts = [
            Shift("Odell", "mon", Span(540, 600)),
            Shift("Odell", "tue", Span(540, 600)),
            Shift("Odell", "wed", Span(540, 600)),
            Shift("Brisa", "mon", Span(540, 1020))
        ]
        self.assertEqual(
            timesheet_lines(shifts), ["Brisa: 1 shift, 8.0 hours", "Odell: 3 shifts, 3.0 hours"]
        )

    def test_hours_to_one_decimal_place(self):
        shifts = [Shift("Quill", "mon", Span(540, 640))]
        self.assertEqual(timesheet_lines(shifts), ["Quill: 1 shift, 1.7 hours"])

    def test_equal_hours_sorted_by_name(self):
        shifts = [
            Shift("Quill", "mon", Span(540, 660)),
            Shift("Brisa", "tue", Span(540, 660))
        ]
        self.assertEqual(
            timesheet_lines(shifts), ["Brisa: 1 shift, 2.0 hours", "Quill: 1 shift, 2.0 hours"]
        )

    def test_empty_list_raises(self):
        with self.assertRaises(ValueError):
            timesheet_lines([])

    def test_blank_worker_name_raises(self):
        shifts = [
            Shift("Brisa", "mon", Span(540, 600)),
            Shift("  ", "tue", Span(540, 600))
        ]
        with self.assertRaises(ValueError):
            timesheet_lines(shifts)
